for _code,_copy in ARCHIVE_COPY.items():
    EXTRA[_code].update(_copy)
for _code,_extra in EXTRA.items():
    L[_code][2].update(_extra)

# Expand locale catalog with core translations. Each app route is a localized copy of the fully functional English screen.
for code,(native,direction,phrases) in L.items():
    code=code.strip()
    if not phrases:
        continue
    text=BASE.read_text()
    # Translate complete quoted strings and plain JSX text nodes, never code identifiers.
    for source,target in sorted(phrases.items(),key=lambda kv:len(kv[0]),reverse=True):
        def quoted(match):
            quote,content=match.group(1),match.group(2)
            if source not in content:return match.group(0)
            escaped=target.replace("\\", "\\\\").replace(quote, "\\"+quote)
            return quote+content.replace(source,escaped)+quote
        def replace_double(match):
            content=match.group(1)
            if content.startswith(('./','../')):return match.group(0)
            return '"'+content.replace(source,target.replace('"','\\"'))+'"' 
        def replace_single(match):
            content=match.group(1)
            if content.startswith(('./','../')):return match.group(0)
            escaped=target.replace('\\','\\\\').replace("'","\\'")
            return "'"+content.replace(source,escaped)+"'"
        text=re.sub(r'"([^"\n]*)"',replace_double,text)
        text=re.sub(r"'([^'\n]*)'",replace_single,text)
        def jsx_text(match):
            content=match.group(1)
            if any(ch in content for ch in "{}=;") or '=>' in content or not re.search(r"[A-Za-z]",content):return match.group(0)
            return '>'+content.replace(source,target)+'<'
        text=re.sub(r">([^<>]*[A-Za-z][^<>]*)<",jsx_text,text)
    text=text.replace("document.documentElement.lang='en';document.documentElement.dir='ltr'",f"document.documentElement.lang='{code}';document.documentElement.dir='{direction}'")
    text=text.replace('dir="ltr"',f'dir="{direction}"')
    text=text.replace('lg:left-0','lg:right-0').replace('lg:ml-64','lg:mr-64').replace('text-left','text-right') if direction=='rtl' else text
    text=text.replace('LanguageSelect current="en"',f'LanguageSelect current="{code}"')
    text=text.replace('language="en"',f'language="{code}"')
    text=text.replace(".toLocaleDateString('en')",f".toLocaleDateString('{code}')").replace(".toLocaleString('en')",f".toLocaleString('{code}')")
    path=ROOT/code/'page.tsx';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(text)
